CREATE OR REPLACE FUNCTION public.guard_business() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prior jsonb; proposed jsonb; key text; sensitive text[]:=ARRAY['name','category','sub','city','area','address','pincode','phone','whatsapp','email','website','description','photos','logo','services','category_id','city_id','locality_id','pincode_id','organization_id','attributes','coordinates','service_areas','structured_hours']; BEGIN
NEW.updated_at:=now(); IF NEW.name='' OR length(NEW.name)>120 OR length(NEW.description)>10000 OR (NEW.pincode<>'' AND NEW.pincode !~ '^[0-9]{6}$') THEN RAISE EXCEPTION 'Invalid listing details'; END IF;
IF auth.uid() IS NULL AND current_user IN ('postgres','supabase_admin') THEN RETURN NEW; END IF;
IF NOT public.has_role(auth.uid(),'admin') THEN IF TG_OP='INSERT' THEN NEW.status:='pending'; NEW.plan:='free'; NEW.verified:=false; NEW.sponsored:=false; NEW.admin_note:=NULL; NEW.owner_feedback:=''; NEW.archived_at:=NULL; ELSE
NEW.plan:=OLD.plan; NEW.verified:=OLD.verified; NEW.sponsored:=OLD.sponsored; NEW.admin_note:=OLD.admin_note; NEW.owner_id:=OLD.owner_id; NEW.owner_feedback:=OLD.owner_feedback;
IF NEW.archived_at IS DISTINCT FROM OLD.archived_at THEN IF NEW.archived_at IS NOT NULL THEN NEW.archive_status:=OLD.status; NEW.status:='archived'; ELSE NEW.status:=coalesce(OLD.archive_status,'pending'); END IF; ELSE
NEW.status:=CASE WHEN OLD.status='rejected' THEN 'pending' ELSE OLD.status END;
IF OLD.status='approved' THEN prior:=to_jsonb(OLD); proposed:=to_jsonb(NEW); IF EXISTS(SELECT 1 FROM unnest(sensitive) k WHERE prior->k IS DISTINCT FROM proposed->k) THEN INSERT INTO public.listing_change_requests(business_id,requester_id,before_data,proposed_data) VALUES(OLD.id,auth.uid(),prior,proposed); FOREACH key IN ARRAY sensitive LOOP proposed:=jsonb_set(proposed,ARRAY[key],coalesce(prior->key,'null'::jsonb)); END LOOP; NEW:=jsonb_populate_record(NEW,proposed); END IF; END IF; END IF; END IF; END IF;
IF NEW.archived_at IS NOT NULL THEN NEW.status:='archived'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_offering_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.updated_at:=now(); IF TG_OP='UPDATE' AND NOT (public.has_role(auth.uid(),'admin') AND current_setting('app.directory_merge',true)='true') THEN NEW.business_id:=OLD.business_id; END IF;
IF NOT public.has_role(auth.uid(),'admin') THEN NEW.review_feedback:=CASE WHEN TG_OP='UPDATE' THEN OLD.review_feedback ELSE '' END; IF NEW.published OR NEW.review_state='published' THEN NEW.review_state:='review'; END IF; END IF;
IF NEW.review_state='published' AND public.obvious_placeholder(NEW.description) AND current_setting('app.directory_merge',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Development or placeholder content must be corrected before publication'; END IF;
NEW.published:=(NEW.review_state='published'); IF NEW.minimum_area<0 OR NEW.minimum_quantity<0 THEN RAISE EXCEPTION 'Minimum values must not be negative'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.merge_directory_businesses(source_id uuid,target_id uuid,reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.businesses; t public.businesses; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF source_id=target_id OR length(trim(reason))<5 THEN RAISE EXCEPTION 'Choose distinct listings and record a reason'; END IF; PERFORM id FROM public.businesses WHERE id IN(source_id,target_id) ORDER BY id FOR UPDATE; SELECT * INTO s FROM public.businesses WHERE id=source_id; SELECT * INTO t FROM public.businesses WHERE id=target_id; IF s.id IS NULL OR t.id IS NULL OR s.archived_at IS NOT NULL OR t.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Listings unavailable'; END IF;
UPDATE public.reviews SET business_id=target_id WHERE business_id=source_id; UPDATE public.leads SET business_id=target_id WHERE business_id=source_id; PERFORM set_config('app.directory_merge','true',true); UPDATE public.business_offerings SET business_id=target_id WHERE business_id=source_id; PERFORM set_config('app.directory_merge','false',true);
INSERT INTO public.favourites(user_id,business_id) SELECT user_id,target_id FROM public.favourites WHERE business_id=source_id ON CONFLICT DO NOTHING;
UPDATE public.directory_quality_issues SET business_id=target_id WHERE business_id=source_id; UPDATE public.listing_change_requests SET business_id=target_id WHERE business_id=source_id;
INSERT INTO public.directory_redirects(kind,from_key,to_key) VALUES('business',source_id::text,target_id::text) ON CONFLICT(kind,from_key) DO UPDATE SET to_key=EXCLUDED.to_key; UPDATE public.directory_redirects SET to_key=target_id::text WHERE kind='business' AND to_key=source_id::text;
UPDATE public.businesses SET archive_status=status,archived_at=now(),status='archived' WHERE id=source_id;
INSERT INTO public.directory_audit(business_id,entity_id,action,actor_id,before_data,after_data,note) VALUES(target_id,source_id,'merge',auth.uid(),to_jsonb(s),to_jsonb(t),reason); END $$;